/// A simple row-major matrix type.
pub type Matrix<T> = Vec<Vec<T>>;

/// Broadcast a 1D vector `a` into an `R x C` matrix according to `shape = [R, C]`.
///
/// Rules:
/// - If `a.len() == R`, treat `a` as a column vector: ret[i][j] = a[i]
/// - Else (so `a.len() == C`), treat `a` as a row vector: ret[i][j] = a[j]
pub fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    assert!(!a.is_empty(), "input array must have positive length");
    assert!(shape.len() == 2, "shape must have length 2");

    let r = shape[0] as usize;
    let c = shape[1] as usize;

    assert!(r > 0 && c > 0, "shape entries must be positive");

    let n = a.len();
    assert!(
        n == r || n == c,
        "array length must match either R or C for broadcasting"
    );

    let mut ret: Matrix<i8> = vec![vec![0i8; c]; r];

    if n == r {
        // Column vector: replicate a[i] across columns
        for i in 0..r {
            let v = a[i];
            for j in 0..c {
                ret[i][j] = v;
            }
        }
    } else {
        // Row vector: replicate a[j] across rows
        for i in 0..r {
            for j in 0..c {
                ret[i][j] = a[j];
            }
        }
    }

    ret
}